UPDATE orders
SET status = #{toStatus},
    cancel_time = #{cancelTime},
    update_time = #{cancelTime}
WHERE order_id = #{orderId}
  AND status = #{fromStatus}

UPDATE orders
SET stock_status = #{toStatus},
    update_time = #{updateTime}
WHERE order_id = #{orderId}
  AND stock_status = #{fromStatus}
